import java.io.*;

public class Main {
    public static void main(String[] args) {
        try {
            FileReader fr = new FileReader("missing.txt");
        } catch (FileNotFoundException e) {
            System.out.println("File not found specifically");
        } catch (Exception e) {
            System.out.println("General error");
        }
    }
}
